query Query {
  servicingGetOrder {
    originDestinationAssociations {
      oDLabel
      originDestination {
        originAirport
        destinationAirport
        distance
        duration
      }
    }
    customerDetails {
      title
      custId
      ptc
      firstName
      lastName
      firstNameNumber
      lastNameNumber
      gender
      dateOfBirth
      contacts {
        email
        phone
        countrycode
      }
      addresses {
        addressLine1
        addressLine2
        addressLine3
        city
        postalCode
        region
        country
      }
      loyaltyMemberDetails {
        memberType
        programName
        memberNumber
        status
        programCode
      }
    }
    orderInstructions {
      itemType
      itemCode
      itemText
      status
      instructionId
    }
    segmentDetails {
      airCraft
      marketingCarrier
      marketingFlightNumber
      operatingCarrier
      operatingFlightNumber
      originAirportCode
      originAirportName
      originCityCode
      originCountryCode
      originCountryName
      destinationAirportCode
      destinationAirportName
      destinationCityCode
      destinationCountryCode
      destinationCountryName
      classOfService
      scheduledArrivalTime {
        utcDateTime
        localDateTime
      }
      scheduledDepartureTime {
        utcDateTime
        localDateTime
      }
      legs {
        legSequenceNumber
        originAirportCode
        operatingCarrier
        destination_Airport_Code
        legDuration
        legDistance {
          unit
          distance
        }
      }
      segmentNumber
      segmentId
      numberInParty
      flightDuration
      flightDistance {
        unit
        distance
      }
    }
    pointOfSale {
      iATANumber
      cityCode
      agencyId
      partyName
      agentId
      deviceType
      ipAddress
      browserType
      countryCode
    }
    creationDateTime {
      localDateTime
      utcDateTime
    }
    orderNumber {
      orderId
      ownerAirline
    }
    bookingReferences {
      airlineDesignator
      rLOC
      rLOCCreateDate
      externalRecordLocator
    }
    paymentDetails {
      formOfPayment
      amount {
        monetaryAmount
        decimalPrecisionCnt
        baseCurrency
      }
      bSPMethod
      cardMethod {
        cardType
        cardNumber
        isTokenised
        issueDate
        expiryDate
        cardholderName
        cVV
        billingAddress {
          addressLine1
          addressLine2
          addressLine3
          city
          postalCode
          region
          country
        }
      }
      payer {
        firstName
        lastName
      }
      voucherMethod {
        voucherType
        issuer
        voucherNumber
        issueDate
        expiryDate
        percentage
      }
    }
    orderItems {
      orderItemId
      ownerAirline
      offerIdReference
      offerItemIdReference
      services {
        serviceId
        productOrder {
          productOwner
          productCode
          productName
          productType
        }
        productSegmentAssociation {
          flightSegmentIds
        }
        currentSeatAssignment
        serviceBeneficiaries
        orderInstructionRefs
        serviceStatus {
          timeStamp
          status
        }
      }
      priceDetails {
        priceComponentType
        priceComponentName
      }
      accountableDocumentRefs {
        documentType
        documentNumber
        documentIssuer
        issueDate
        customerRefId
        fareCalculation
        coupons {
          checkDigit
          couponNumber
          couponStatus
          segmentRefId
          fareBasis
          designator
        }
      }
      pNRReferences
      itemStatus {
        timeStamp
        status
      }
      orderItemPenalties {
        type
        percentage
        link
        text
      }
    }
    orderStatus
  }
}
